const upsertAppConfig = `-- name: UpsertAppConfig :exec
INSERT INTO app_config (app_id, name, is_secret, value_plain, value_cipher, updated_by, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, now())
ON CONFLICT (app_id, name) DO UPDATE SET
    is_secret = EXCLUDED.is_secret, value_plain = EXCLUDED.value_plain, value_cipher = EXCLUDED.value_cipher,
    updated_by = EXCLUDED.updated_by, updated_at = now()
`

type UpsertAppConfigParams struct {
	AppID       int64       `json:"app_id"`
	Name        string      `json:"name"`
	IsSecret    bool        `json:"is_secret"`
	ValuePlain  string      `json:"value_plain"`
	ValueCipher []byte      `json:"value_cipher"`
	UpdatedBy   pgtype.Int8 `json:"updated_by"`
}

func (q *Queries) UpsertAppConfig(ctx context.Context, arg UpsertAppConfigParams) error {
	_, err := q.db.Exec(ctx, upsertAppConfig,
		arg.AppID,
		arg.Name,
		arg.IsSecret,
		arg.ValuePlain,
		arg.ValueCipher,
		arg.UpdatedBy,
	)
	return err
}

const upsertSharedApp = `-- name: UpsertSharedApp :one
INSERT INTO shared_apps (app_id, slug, always_on, idle_minutes, memory_mb, cpus, health_path, port, wants_db)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (app_id) DO UPDATE SET
    always_on = EXCLUDED.always_on, idle_minutes = EXCLUDED.idle_minutes, memory_mb = EXCLUDED.memory_mb,
    cpus = EXCLUDED.cpus, health_path = EXCLUDED.health_path, port = EXCLUDED.port, wants_db = EXCLUDED.wants_db,
    unshared_at = NULL
RETURNING app_id, slug, status, always_on, idle_minutes, memory_mb, cpus, health_path, port, wants_db, db_name, current_deployment_id, previous_deployment_id, restart_count, restart_window_start, last_access_at, status_changed_at, status_message, acks, stopped_by, unshared_at, created_at
`

type UpsertSharedAppParams struct {
	AppID       int64          `json:"app_id"`
	Slug        string         `json:"slug"`
	AlwaysOn    bool           `json:"always_on"`
	IdleMinutes int32          `json:"idle_minutes"`
	MemoryMb    int32          `json:"memory_mb"`
	Cpus        pgtype.Numeric `json:"cpus"`
	HealthPath  string         `json:"health_path"`
	Port        int32          `json:"port"`
	WantsDb     bool           `json:"wants_db"`
}

func (q *Queries) UpsertSharedApp(ctx context.Context, arg UpsertSharedAppParams) (SharedApp, error) {
	row := q.db.QueryRow(ctx, upsertSharedApp,
		arg.AppID,
		arg.Slug,
		arg.AlwaysOn,
		arg.IdleMinutes,
		arg.MemoryMb,
		arg.Cpus,
		arg.HealthPath,
		arg.Port,
		arg.WantsDb,
	)
	var i SharedApp
	err := row.Scan(
		&i.AppID,
		&i.Slug,
		&i.Status,
		&i.AlwaysOn,
		&i.IdleMinutes,
		&i.MemoryMb,
		&i.Cpus,
		&i.HealthPath,
		&i.Port,
		&i.WantsDb,
		&i.DbName,
		&i.CurrentDeploymentID,
		&i.PreviousDeploymentID,
		&i.RestartCount,
		&i.RestartWindowStart,
		&i.LastAccessAt,
		&i.StatusChangedAt,
		&i.StatusMessage,
		&i.Acks,
		&i.StoppedBy,
		&i.UnsharedAt,
		&i.CreatedAt,
	)
	return i, err
}

